-- 운영 콘텐츠 번역: 원문은 기존 컬럼, 다른 언어는 translations jsonb { kr|en|mn: { 필드: 값 } }
alter table public.study_infos add column if not exists translations jsonb not null default '{}'::jsonb;
alter table public.community_groups add column if not exists translations jsonb not null default '{}'::jsonb;
alter table public.freelancer_groups add column if not exists translations jsonb not null default '{}'::jsonb;
update public.study_infos set translations = $j${"en": {"title": "Your first week in Korea: a realistic plan", "summary": "A checklist that covers arrival, school support and everyday essentials in one place.", "audience": "Students about to arrive and new arrivals", "tags": ["Arrival", "First week", "Checklist"], "content": "You don't have to sort everything out in the first week. Start by making sure you can reach your accommodation, contact someone who can help, and find reliable information. The order below is a suggestion, not an official schedule. Adjust it to your arrival time, your school's guidance and your situation.\n\n## Before you leave | Keep key information within reach.\nCheck the arrival guidance from your school or accommodation before any generic checklist. Save travel details, bookings and important contacts so you can open them offline. Confirm which documents you need for your status with HiKorea or your consulate.\n- [ ] Save your accommodation address in Korean and English\n- [ ] Save your school's arrival guide and contacts\n- [ ] Prepare copies of the documents the authorities asked for\n\n## Arrival | Secure a safe place to stay and your contacts first.\nPlan your route using official airport and operator information, including hours and payment methods. Let someone you trust know you have arrived. If your accommodation is uncertain, contact the accommodation or your school before making unfamiliar payments or handing over ID.\n- [ ] Check how to get to your accommodation and how check-in works\n- [ ] Find your school or local support contacts\n- [ ] Note emergency and accommodation contacts\n\n## The first few days | Ask about admin before guessing the rules.\nYour school's international office is a good place to start campus tasks. Ask where notices are posted and which office handles what. Alien registration, address reporting and work permission depend on your status, so check with the relevant authority. For health insurance, check both the National Health Insurance guidance and your school's support.\n- [ ] Ask the international office about orientation and campus procedures\n- [ ] Check the obligations and deadlines for your status\n- [ ] List your questions about hospitals and insurance\n\n## Settling in | Set up what you use every day.\nDaily life gets much easier once your phone, bank account and transport are ready. Requirements differ by company and document, so ask what you need before you visit. For housing, understand the deposit, maintenance fees and contract terms, and know who can help you review them. Finally, plan some rest time too.\n- [ ] Check phone plan and bank account requirements directly\n- [ ] Understand your housing contract before signing or paying\n- [ ] Write down open questions and where to check them"}, "mn": {"title": "Солонгос дахь эхний долоо хоног: бодит төлөвлөгөө", "summary": "Ирэх, сургуулийн дэмжлэг, өдөр тутмын зайлшгүй бэлтгэлийг нэг дор багтаасан шалгах жагсаалт.", "audience": "Удахгүй ирэх болон шинээр ирсэн оюутнууд", "tags": ["Ирэх", "Эхний долоо хоног", "Шалгах жагсаалт"], "content": "Эхний долоо хоногт бүх зүйлийг шийдэх шаардлагагүй. Эхлээд байрандаа хүрч чадах эсэх, туслах хүнтэйгээ холбогдож чадах эсэх, найдвартай мэдээлэл харж чадах эсэхээ шалгаарай. Доорх дараалал нь албан ёсны хуваарь биш, зөвхөн санал юм. Ирэх цаг, сургуулийн заавар, өөрийн нөхцөлд тохируулан өөрчилнө үү.\n\n## Явахаас өмнө | Чухал мэдээллээ гарын дор байлгаарай.\nЕрөнхий жагсаалтаас өмнө сургууль эсвэл байрны зүгээс өгсөн ирэх зааврыг шалгаарай. Аяллын мэдээлэл, захиалга, чухал холбоо барих хаягаа интернэтгүй үед ч нээж болохоор хадгална уу. Ямар бичиг баримт хэрэгтэйг өөрийн визийн ангиллаар HiKorea эсвэл харьяа консулын газраас тодруулаарай.\n- [ ] Байрны хаягаа солонгос, англиар хадгалах\n- [ ] Сургуулийн ирэх заавар, холбоо барих мэдээллийг хадгалах\n- [ ] Холбогдох байгууллагын шаардсан бичиг баримтын хуулбар бэлдэх\n\n## Ирэх үед | Эхлээд аюулгүй байр, холбоо барих хүнээ баталгаажуулаарай.\nНисэх буудал, тээврийн компанийн албан ёсны мэдээллээр замаа төлөвлөж, ажиллах цаг, төлбөрийн хэлбэрийг урьдчилан шалгаарай. Ирснээ итгэлтэй хүндээ мэдэгдээрэй. Байрны асуудал тодорхойгүй бол танихгүй төлбөр хийх, иргэний үнэмлэхээ өгөхөөс өмнө байр эсвэл сургуультайгаа холбогдоно уу.\n- [ ] Байр руу очих зам, бүртгүүлэх журмыг шалгах\n- [ ] Сургууль эсвэл орон нутгийн дэмжлэгийн холбоо барих мэдээллийг тодруулах\n- [ ] Яаралтай тусламж болон байрны утсыг тэмдэглэх\n\n## Эхний хэдэн өдөр | Журмыг таахаас өмнө захиргааны асуудлаа асуугаарай.\nСургуулийн гадаад харилцааны алба кампусын ажлыг эхлүүлэхэд хамгийн тохиромжтой газар. Мэдээлэл хаана нийтлэгддэг, аль хэлтэс ямар асуудал хариуцдагийг асуугаарай. Гадаадын иргэний бүртгэл, хаягийн мэдүүлэг, ажиллах зөвшөөрөл нь визийн ангиллаас хамаарч өөр байж болох тул холбогдох байгууллагаас шууд тодруулна уу. Эрүүл мэндийн даатгалын талаар Үндэсний эрүүл мэндийн даатгалын заавар болон сургуулийн дэмжлэгийг хамтад нь шалгаарай.\n- [ ] Гадаад харилцааны албанаас танилцуулга, кампусын журмыг асуух\n- [ ] Өөрийн визийн үүрэг, хугацааг шалгах\n- [ ] Эмнэлэг, даатгалын талаарх асуултаа жагсаах\n\n## Амьдралаа цэгцлэх | Өдөр бүр хэрэглэх зүйлсээсээ эхлээрэй.\nУтас, банк, тээвэр бэлэн болбол өдөр тутмын амьдрал хамаагүй хялбар болно. Гэхдээ шаардлага нь компани, бичиг баримтаас хамаарч өөр байдаг тул очихоосоо өмнө юу хэрэгтэйг асуугаарай. Байрны хувьд барьцаа, ашиглалтын төлбөр, гэрээний нөхцөлийг ойлгож, хэн хянахад тусалж чадахыг мэдэж аваарай. Эцэст нь амрах цагаа ч төлөвлөгөөндөө оруулаарай.\n- [ ] Утасны дугаар нээх, банкны данс нээх шаардлагыг шууд тодруулах\n- [ ] Гарын үсэг зурах, төлбөр хийхээс өмнө байрны гэрээний нөхцөлийг ойлгох\n- [ ] Шийдэгдээгүй асуулт, хаанаас шалгахаа товч тэмдэглэх"}}$j$::jsonb where id = '2ee8443a-9844-40f7-87ac-4dba3740a187';
update public.study_infos set translations = $j${"en": {"title": "Who to ask on campus", "summary": "Where to start with academic, international office and student support questions.", "audience": "Students in their first semester", "tags": ["Academics", "International office"], "content": "The same question can get different answers from different offices. First decide what kind of question it is, then ask the office that handles it.\n\n## Academics | Ask your department and academic affairs about classes, grades and registration.\nCourse registration periods, credit transfer and grade issues are usually handled by your department office or the academic affairs team. Check notices on the school portal first, and if you can't find the answer, email your department's assistant.\n- [ ] Save your department office location and email\n- [ ] Add course registration and change periods to your calendar\n\n## International office | Start here for stay matters and orientation.\nEnrollment certificates, guidance on stay documents and international student orientation usually begin at the international office. For final decisions on your stay, also check the immigration authority's guidance.\n- [ ] Check the international office's consultation hours\n- [ ] Keep the orientation materials\n\n## Student support | Find the dedicated office for counseling, scholarships and dorms.\nMany schools have separate offices such as a counseling center, scholarship team and dormitory office. Names differ by school, so check the department list on the portal.\n- [ ] Find out how to book the counseling center\n- [ ] Save where scholarship notices are posted"}, "mn": {"title": "Кампус дээр хэнээс асуух вэ", "summary": "Хичээл, гадаад харилцааны алба, оюутны дэмжлэгийн асуултаа хаанаас эхлэхийг цэгцэлсэн заавар.", "audience": "Эхний улиралдаа суралцаж буй оюутнууд", "tags": ["Хичээл", "Гадаад харилцааны алба"], "content": "Нэг асуултад хэлтэс бүр өөр хариулт өгч болно. Эхлээд асуултаа ямар төрлийнх болохыг ялгаад, тухайн ажлыг хариуцдаг газраас асуугаарай.\n\n## Сургалт | Хичээл, дүн, хичээл сонголтыг тэнхим болон сургалтын албанаас асуугаарай.\nХичээл сонгох хугацаа, кредит тооцуулах, дүнгийн асуудлыг ихэвчлэн харьяа тэнхим эсвэл сургалтын алба хариуцдаг. Эхлээд сургуулийн порталын мэдээллийг шалгаж, хариулт олдохгүй бол тэнхимийн туслахад имэйл бичээрэй.\n- [ ] Тэнхимийн өрөөний байршил, имэйлийг хадгалах\n- [ ] Хичээл сонгох, өөрчлөх хугацааг хуанлидаа тэмдэглэх\n\n## Гадаад харилцааны алба | Оршин суух асуудал, танилцуулга эндээс эхэлнэ.\nСуралцаж буйг нотлох лавлагаа, оршин суухтай холбоотой бичиг баримтын заавар, гадаад оюутны танилцуулга ихэвчлэн гадаад харилцааны албанаас эхэлдэг. Оршин суухтай холбоотой эцсийн шийдвэрийн талаар цагаачлалын байгууллагын зааврыг хамт шалгаарай.\n- [ ] Гадаад харилцааны албаны зөвлөгөө өгөх цагийг шалгах\n- [ ] Танилцуулгын материалыг авч хадгалах\n\n## Оюутны дэмжлэг | Зөвлөгөө, тэтгэлэг, дотуур байрны асуудлыг хариуцсан албыг олоорой.\nОюутны зөвлөгөөний төв, тэтгэлгийн алба, дотуур байрны алба гэх мэт тусгай хэлтсүүд ихэвчлэн байдаг. Сургууль бүрт нэр нь өөр тул порталаас хэлтсийн жагсаалтыг шалгаарай.\n- [ ] Оюутны зөвлөгөөний төвд цаг захиалах аргыг мэдэж авах\n- [ ] Тэтгэлгийн мэдээлэл хаана гардгийг хадгалах"}}$j$::jsonb where id = 'a776caa7-dbfb-422d-8d01-7b2b3fbf35ad';
update public.study_infos set translations = $j${"en": {"title": "Questions to ask before renting a room", "summary": "A checklist for viewings and the questions to ask before you sign.", "audience": "Students looking for housing for the first time", "tags": ["Housing", "Contract", "Deposit"], "content": "The contract matters more than the photos. Prepare separately for before the viewing, before signing and after moving in.\n\n## Before viewing | Set your budget and conditions first.\nDecide your monthly limit including rent, deposit and maintenance fees, and narrow the area by commute time to school. Using a licensed real estate agent or channels your school recommends lowers the risk of fraud.\n- [ ] Set your monthly budget and deposit limit\n- [ ] List preferred areas and commute times\n\n## Before signing | Check the owner and the terms.\nUse the property register (deunggibu deungbon) to confirm the real owner and any mortgage. Read the deposit return terms, what the maintenance fee includes and early termination terms carefully. Ask about any clause you don't understand before you sign.\n- [ ] Confirm the owner in the property register\n- [ ] Check what the maintenance fee includes\n- [ ] Check the terms for early termination\n\n## After moving | Don't forget to report your new address.\nAfter moving, you must report your change of address within the set period. Check the deadline and method on HiKorea or with the relevant office.\n- [ ] Check the deadline for reporting your change of address"}, "mn": {"title": "Байр түрээслэхээс өмнө тодруулах асуултууд", "summary": "Байр үзэхэд хэрэглэх шалгах жагсаалт, гэрээ байгуулахаас өмнө асуух асуултууд.", "audience": "Анх удаа байр хайж буй оюутнууд", "tags": ["Байр", "Гэрээ", "Барьцаа"], "content": "Байрны хувьд зурагнаас илүү гэрээ чухал. Үзэхээс өмнө, гэрээ байгуулахаас өмнө, нүүсний дараа шалгах зүйлсээ тусад нь бэлдээрэй.\n\n## Үзэхээс өмнө | Төсөв, нөхцөлөө эхлээд тодорхойлоорой.\nСарын түрээс, барьцаа, ашиглалтын төлбөрийг нийлүүлсэн сарын зардлын дээд хязгаараа тогтоож, сургууль хүртэлх замын хугацаагаар бүсээ нарийсгаарай. Лицензтэй үл хөдлөх хөрөнгийн зуучлагч эсвэл сургуулийн санал болгосон сувгаар хайвал луйврын эрсдэл буурна.\n- [ ] Сарын төсөв, барьцааны дээд хэмжээгээ тогтоох\n- [ ] Хүссэн бүс, сургууль хүртэлх замын хугацааг жагсаах\n\n## Гэрээ байгуулахаас өмнө | Эзэмшигч болон нөхцөлийг шалгаарай.\nҮл хөдлөх хөрөнгийн бүртгэлийн хуулбараар (등기부등본) жинхэнэ эзэмшигч, барьцаалагдсан эсэхийг шалгаарай. Барьцаа буцаах нөхцөл, ашиглалтын төлбөрт багтах зүйлс, гэрээг хугацаанаас өмнө цуцлах нөхцөлийг сайтар уншаарай. Ойлгохгүй заалтыг гарын үсэг зурахаас өмнө заавал асуугаарай.\n- [ ] Бүртгэлийн хуулбараар эзэмшигчийг шалгах\n- [ ] Ашиглалтын төлбөрт юу багтдагийг шалгах\n- [ ] Хугацаанаас өмнө цуцлах нөхцөлийг шалгах\n\n## Нүүсний дараа | Хаяг өөрчилснөө мэдүүлэхээ бүү мартаарай.\nНүүсний дараа тогтоосон хугацаанд оршин суух хаягийн өөрчлөлтөө мэдүүлэх ёстой. Хугацаа, журмыг HiKorea эсвэл харьяа байгууллагаас шалгаарай.\n- [ ] Хаягийн өөрчлөлт мэдүүлэх хугацааг шалгах"}}$j$::jsonb where id = '276d8322-8c85-4e92-b7a7-7852b8626e8b';
update public.study_infos set translations = $j${"en": {"title": "Getting started with healthcare in Korea", "summary": "How to get treatment, language support, and what to ask about insurance.", "audience": "Students using a Korean hospital for the first time", "tags": ["Hospital", "Health insurance"], "content": "Finding a clinic for the first time when you are sick can be stressful. Knowing where to go and what to bring in advance makes it much easier. This guide is not medical advice. Get any judgment about symptoms from medical staff.\n\n## Choosing a clinic | Start with a local clinic for mild symptoms.\nColds and minor pain are usually treated at a nearby clinic (uiwon), which can refer you to a hospital if detailed tests are needed. In an emergency, call 119.\n- [ ] Find clinics near your home and school\n- [ ] Check whether treatment is available in a language you speak\n\n## At the clinic | Bring your ID and keep records.\nClinics often ask for your residence card at registration. Keep receipts and itemized bills, as you may need them for insurance claims later.\n- [ ] Bring your residence card\n- [ ] Keep receipts and itemized bills\n\n## Insurance | Check your enrollment in advance.\nWho must enroll in health insurance and how much it costs depends on your status and situation. Check both the National Health Insurance guidance and your school's support.\n- [ ] Check your health insurance status"}, "mn": {"title": "Солонгост эмнэлгийн үйлчилгээ авч эхлэх нь", "summary": "Үзлэгт хэрхэн орох, хэлний дэмжлэг, даатгалын талаар юу асуухыг цэгцэлсэн заавар.", "audience": "Солонгосын эмнэлэгт анх удаа хандах оюутнууд", "tags": ["Эмнэлэг", "Эрүүл мэндийн даатгал"], "content": "Өвдсөн үедээ анх удаа эмнэлэг хайх нь хэцүү байдаг. Хаана очих, юу авч явахаа урьдчилан мэдвэл хамаагүй хялбар болно. Энэ заавар нь эмнэлгийн зөвлөгөө биш. Шинж тэмдгийн талаарх дүгнэлтийг эмч, эмнэлгийн ажилтнаас аваарай.\n\n## Эмнэлэг сонгох | Хөнгөн шинж тэмдэгтэй бол ойролцоох клиникээс эхлээрэй.\nХаниад, хөнгөн өвдөлтийг ихэвчлэн ойролцоох клиникт (의원) үздэг бөгөөд нарийн шинжилгээ шаардлагатай бол том эмнэлэг рүү илгээдэг. Яаралтай тохиолдолд 119 руу залгаарай.\n- [ ] Гэр, сургуулийн ойролцоох клиникийн байршлыг мэдэж авах\n- [ ] Гадаад хэлээр үзлэг хийдэг эсэхийг шалгах\n\n## Үзлэгт орохдоо | Иргэний үнэмлэх, баримтаа авч яваарай.\nБүртгүүлэхэд гадаадын иргэний үнэмлэх шаарддаг нь элбэг. Төлбөрийн баримт, эмчилгээний зардлын дэлгэрэнгүй хуудсыг дараа нь даатгалд нэхэмжлэхэд хэрэг болж магадгүй тул хадгалаарай.\n- [ ] Гадаадын иргэний үнэмлэхээ авч явах\n- [ ] Төлбөрийн баримт, дэлгэрэнгүй хуудсаа хадгалах\n\n## Даатгал | Даатгалдаа хамрагдсан эсэхээ урьдчилан шалгаарай.\nЭрүүл мэндийн даатгалд хамрагдах эсэх, шимтгэлийн хэмжээ нь визийн ангилал, нөхцөлөөс хамаарна. Үндэсний эрүүл мэндийн даатгалын заавар болон сургуулийн дэмжлэгийг хамтад нь шалгаарай.\n- [ ] Эрүүл мэндийн даатгалын төлөвөө шалгах"}}$j$::jsonb where id = '088fdc33-fd18-438b-bce8-09217b2ae007';
update public.study_infos set translations = $j${"en": {"title": "Phone, bank and transport basics", "summary": "Plan ahead for the documents and information you need day to day.", "audience": "Students in their first month after arrival", "tags": ["Phone", "Bank", "Transport"], "content": "Once you have a phone, a bank account and a transport card, most of daily life gets easier. Required documents vary by company, so check before you visit.\n\n## Phone | A number that works for identity verification matters.\nMany Korean services require phone identity verification. The documents needed to open a line depend on the carrier and your status, so ask in advance.\n- [ ] Check the documents your carrier requires\n\n## Bank | Check the account opening requirements.\nEach bank has different requirements for foreigners opening an account. They may ask for your residence card or enrollment certificate, so check before you visit.\n- [ ] Check the requirements of the bank you plan to visit\n\n## Transport | One transport card covers most trips.\nYou can buy and top up a transport card at convenience stores. Installing a subway and bus app makes getting around easier.\n- [ ] Buy and top up a transport card\n- [ ] Install a map and transit app"}, "mn": {"title": "Утас, банк, тээврийн үндсэн бэлтгэл", "summary": "Өдөр тутамд хэрэгтэй бичиг баримт, мэдээллээ урьдчилан төлөвлөөрэй.", "audience": "Ирээд эхний сардаа байгаа оюутнууд", "tags": ["Утас", "Банк", "Тээвэр"], "content": "Утас, банк, тээврийн карт бэлэн болбол өдөр тутмын ихэнх зүйл хялбар болно. Гэхдээ компани бүр өөр бичиг баримт шаарддаг тул очихоосоо өмнө шалгаарай.\n\n## Утас | Хувийн баталгаажуулалт хийх боломжтой дугаар чухал.\nСолонгосын олон үйлчилгээ утсаар хувийн баталгаажуулалт хийхийг шаарддаг. Дугаар нээхэд шаардлагатай бичиг баримт нь операторын компани, визийн төлөвөөс хамаарах тул урьдчилан асуугаарай.\n- [ ] Операторт шаардлагатай бичиг баримтыг шалгах\n\n## Банк | Данс нээх нөхцөлийг шалгаарай.\nБанк бүр гадаадын иргэнд данс нээх өөр нөхцөлтэй. Гадаадын иргэний үнэмлэх, суралцаж буйг нотлох лавлагаа зэрэг шаардаж болох тул очихоосоо өмнө шалгаарай.\n- [ ] Очих банкны данс нээх нөхцөлийг шалгах\n\n## Тээвэр | Нэг тээврийн картаар ихэнх асуудал шийдэгдэнэ.\nТээврийн картыг дэлгүүрээс (편의점) худалдан авч цэнэглэж болно. Метро, автобусны апп суулгавал зам олоход хялбар.\n- [ ] Тээврийн карт худалдан авч цэнэглэх\n- [ ] Газрын зураг, тээврийн апп суулгах"}}$j$::jsonb where id = 'c1891e7a-bbe5-4fb4-9e1f-32f5202141a3';
update public.study_infos set translations = $j${"en": {"title": "Before you take a part-time job", "summary": "Check permission and conditions before you start working.", "audience": "Students considering part-time work or an internship", "tags": ["Part-time", "Employment"], "content": "Before you start working, first check whether your status allows you to work. Working without permission can cause problems for your stay.\n\n## Permission | Check the work conditions for your status first.\nDepending on their status, international students may need prior permission or face limits on hours and job types. Confirm the exact conditions with your school's international office and the immigration authority.\n- [ ] Check the work conditions for your status\n- [ ] Ask the international office about the permission process\n\n## Conditions | Get the terms in writing.\nConfirm your hourly wage, working hours and payday in writing. Also review the official guidance on minimum wage and working conditions.\n- [ ] Get a written employment contract\n- [ ] Check your payday and payment method"}, "mn": {"title": "Цагийн ажил хийхээс өмнө", "summary": "Ажил эхлэхээсээ өмнө зөвшөөрөл, нөхцөлөө эхлээд шалгаарай.", "audience": "Цагийн ажил, дадлага хийх гэж буй оюутнууд", "tags": ["Цагийн ажил", "Хөдөлмөр"], "content": "Ажил эхлэхээсээ өмнө хамгийн түрүүнд өөрийн визээр ажиллах эрхтэй эсэхээ шалгаарай. Зөвшөөрөлгүй ажиллавал оршин суух эрхэд тань асуудал үүсч болно.\n\n## Зөвшөөрөл | Визийн ангиллын дагуух ажиллах нөхцөлийг эхлээд шалгаарай.\nГадаад оюутан визийн ангиллаасаа хамаарч урьдчилан зөвшөөрөл авах, эсвэл ажиллах цаг, салбарын хязгаарлалттай байж болно. Тодорхой нөхцөлийг сургуулийн гадаад харилцааны алба болон цагаачлалын байгууллагаас тодруулаарай.\n- [ ] Өөрийн визийн ажиллах нөхцөлийг шалгах\n- [ ] Шаардлагатай зөвшөөрлийн журмыг гадаад харилцааны албанаас асуух\n\n## Нөхцөл | Гэрээний нөхцөлийг бичгээр аваарай.\nЦагийн хөлс, ажиллах цаг, цалин олгох өдрийг бичгээр баталгаажуулаарай. Хөдөлмөрийн хөлсний доод хэмжээ, хөдөлмөрийн нөхцөлийн албан ёсны мэдээллийг ч хамт үзээрэй.\n- [ ] Хөдөлмөрийн гэрээ авах\n- [ ] Цалин олгох өдөр, хэлбэрийг шалгах"}}$j$::jsonb where id = 'b93edafe-8e40-4b8c-981f-b15da24a41a2';
update public.study_infos set translations = $j${"en": {"title": "Questions to check before departure", "summary": "Sort out flights, school and documents for your own situation.", "audience": "Students preparing to leave for Korea", "tags": ["Departure", "Documents"], "content": "What you need to check before departure differs from person to person. Answer the questions below for your own situation.\n\n## School | Confirm your arrival schedule and support.\nCheck your dormitory move-in date, orientation date and whether airport pickup is offered in your school's guidance.\n- [ ] Check when you can move into the dormitory\n- [ ] Check the orientation schedule\n\n## Documents | Confirm required documents with official guidance.\nVisa and entry documents depend on your status and nationality. Prepare them based on HiKorea and your consulate's guidance.\n- [ ] Check the document list against official guidance\n- [ ] Save digital copies of your documents"}, "mn": {"title": "Явахаас өмнө шалгах асуултууд", "summary": "Нислэг, сургууль, бичиг баримтын асуудлаа өөрийн нөхцөлд тохируулан цэгцлээрэй.", "audience": "Солонгос руу явахаар бэлтгэж буй оюутнууд", "tags": ["Явах", "Бичиг баримт"], "content": "Явахаас өмнө шалгах зүйл хүн бүрт өөр. Доорх асуултад өөрийн нөхцөлөөр хариулаарай.\n\n## Сургууль | Ирэх хуваарь, дэмжлэгээ тодруулаарай.\nДотуур байранд орох өдөр, танилцуулгын өдөр, нисэх буудлаас тосох эсэхийг сургуулийн заавраас шалгаарай.\n- [ ] Дотуур байранд орох боломжтой өдрийг шалгах\n- [ ] Танилцуулгын хуваарийг шалгах\n\n## Бичиг баримт | Шаардлагатай бичиг баримтыг албан ёсны заавраар шалгаарай.\nВиз болон хил нэвтрэх бичиг баримт нь визийн ангилал, иргэншлээс хамаарна. HiKorea болон харьяа консулын газрын зааврыг үндэслэн бэлтгээрэй.\n- [ ] Шаардлагатай бичиг баримтын жагсаалтыг албан ёсны заавраар шалгах\n- [ ] Бичиг баримтын хуулбарыг цахимаар хадгалах"}}$j$::jsonb where id = 'df3885db-cd75-4863-95df-70bb9d08a1e0';
update public.community_groups set translations = $j${"en": {"name": "Sinchon International Student Meetup", "description": "Students around Sinchon and Hongdae meet once a month to share a meal and useful information.", "tags": ["Sinchon", "Meetup"]}, "mn": {"name": "Синчон дахь гадаад оюутнуудын уулзалт", "description": "Синчон, Хундэ орчмын гадаад оюутнууд сард нэг удаа уулзаж, хамт хооллон мэдээлэл солилцдог бүлэг.", "tags": ["Синчон", "Уулзалт"]}}$j$::jsonb where id = 'd2000000-0000-4000-a000-000000000001';
update public.community_groups set translations = $j${"kr": {"name": "서울의 몽골 유학생", "description": "서울에서 공부하는 몽골 유학생들이 정보를 나누고 함께 만나는 모임이에요.", "tags": ["몽골", "서울"]}, "en": {"name": "Mongolian Students in Seoul", "description": "A group for Mongolian students studying in Seoul to share information and meet up.", "tags": ["Mongolia", "Seoul"]}}$j$::jsonb where id = 'd2000000-0000-4000-a000-000000000002';
update public.community_groups set translations = $j${"en": {"name": "D-2 → D-10 Visa Info Room", "description": "Share your experience extending or changing your visa. This is a space for sharing experience, not legal advice.", "tags": ["Visa", "D-10"]}, "mn": {"name": "D-2 → D-10 визийн мэдээллийн бүлэг", "description": "Виз сунгах, шилжүүлэх туршлагаа хуваалцах бүлэг. Энд хууль зүйн зөвлөгөө бус, зөвхөн туршлага хуваалцана.", "tags": ["Виз", "D-10"]}}$j$::jsonb where id = 'd2000000-0000-4000-a000-000000000003';
update public.community_groups set translations = $j${"kr": {"name": "TOPIK 스터디 (한/영)", "description": "매주 한국어와 영어로 진행하는 TOPIK 스터디예요. 모든 급수 환영해요.", "tags": ["TOPIK", "스터디"]}, "mn": {"name": "TOPIK сургалтын бүлэг (KR/EN)", "description": "Долоо хоног бүр солонгос, англи хэлээр TOPIK-д бэлтгэнэ. Бүх түвшний оюутан нэгдэх боломжтой.", "tags": ["TOPIK", "Сургалт"]}}$j$::jsonb where id = 'd2000000-0000-4000-a000-000000000004';
update public.community_groups set translations = $j${"en": {"name": "Part-time Jobs & Internships", "description": "Share part-time and internship openings international students can apply for, plus reviews. Always check whether your visa allows the work.", "tags": ["Part-time", "Internship"]}, "mn": {"name": "Цагийн ажил, дадлагын мэдээлэл", "description": "Гадаад оюутнуудад нээлттэй цагийн ажил, дадлагын зар болон сэтгэгдлээ хуваалцана. Таны виз ажиллах эрх олгодог эсэхийг заавал шалгаарай.", "tags": ["Цагийн ажил", "Дадлага"]}}$j$::jsonb where id = 'd2000000-0000-4000-a000-000000000005';
update public.freelancer_groups set translations = $j${"en": {"name": "Translation & Interpreting (KR/EN/MN)", "description": "A group for Korean, English and Mongolian translation and interpreting projects."}, "mn": {"name": "Орчуулга, хэлмэрч (KR/EN/MN)", "description": "Солонгос, англи, монгол хэлний орчуулга, хэлмэрчийн төслүүдийг хамтран гүйцэтгэх бүлэг."}}$j$::jsonb where id = 'd3000000-0000-4000-a000-000000000001';
update public.freelancer_groups set translations = $j${"en": {"name": "Design & Video Editing", "description": "A group for collaborating on posters, social media content and video editing projects."}, "mn": {"name": "Дизайн, видео эвлүүлэг", "description": "Постер, сошиал контент, видео эвлүүлгийн төслүүд дээр хамтран ажиллах бүлэг."}}$j$::jsonb where id = 'd3000000-0000-4000-a000-000000000002';
